-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by ap_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_accounts_payable') }}
    where _dq_is_valid
